class Solution:
    def maximumEvenSplit(self, finalSum: int) -> List[int]:
        if finalSum % 2 != 0:
            return []
        res = []
        cur = 2
        while finalSum >= cur:
            res.append(cur)
            finalSum -= cur
            cur += 2
        res[-1] += finalSum
        return res

class Solution {
public:
    vector<long long> maximumEvenSplit(long long finalSum) {
        if (finalSum % 2 != 0) return {};
        vector<long long> res;
        long long cur = 2;
        while (finalSum >= cur) {
            res.push_back(cur);
            finalSum -= cur;
            cur += 2;
        }
        res.back() += finalSum;
        return res;
    }
};

class Solution {
    public List<Long> maximumEvenSplit(long finalSum) {
        if (finalSum % 2 != 0) return new ArrayList<>();
        List<Long> res = new ArrayList<>();
        long cur = 2;
        while (finalSum >= cur) {
            res.add(cur);
            finalSum -= cur;
            cur += 2;
        }
        int lastIdx = res.size() - 1;
        res.set(lastIdx, res.get(lastIdx) + finalSum);
        return res;
    }
}

var maximumEvenSplit = function(finalSum) {
    let sum = BigInt(finalSum);
    if (sum % 2n !== 0n) return [];
    const res = [];
    let cur = 2n;
    while (sum >= cur) {
        res.push(cur);
        sum -= cur;
        cur += 2n;
    }
    res[res.length - 1] += sum;
    return res.map(Number);
};
